const nodes = $input.first().json.data.repository.discussions.nodes;

// "[카테고리]"로 시작하는 실제 질문 Discussion만 필터링
const questionsOnly = nodes.filter(n => n.title.startsWith('['));

// Gemini 프롬프트에 넣을 이력 텍스트 (제목 + 본문 질문 요약)
const historyText = questionsOnly.map(n => {
  // body에서 마크다운 구조를 걷어내고 핵심 질문 문장만 뽑기
  const match = n.body.match(/\*\*\[.+?\]\*\*\s*(.+?)\n\n---/s);
  const questionText = match ? match[1].trim() : n.body;
  return `- ${n.title}: ${questionText}`;
}).join('\n');

// 현재 열려있는(닫히지 않은) 질문 Discussion의 id 찾기 (5단계 Close에서 사용)
const openOne = questionsOnly.find(n => !n.closed);

return [{
  json: {
    recentTitlesText: historyText,
    openDiscussionId: openOne ? openOne.id : null
  }
}];

const history = $input.first().json.recentTitlesText;

const prompt = `너는 신입~주니어 개발자 기술면접 질문 큐레이터다.

역할:
1. 웹 검색으로 "최근 신입/주니어 개발자 기술면접 기출 질문"이나 "요즘 뜨는 개발자 면접 트렌드"를 찾아라.
2. 검색된 질문/주제 중 아래 조건을 모두 만족하는 것만 선별하라:
   - 특정 프로그래밍 언어 문법이나 특정 프레임워크(React, Vue, Spring, Django 등) 세부 API를 직접 묻지 않을 것
   - 특정 클라우드 벤더(AWS, GCP, Azure 등) 특정 서비스명을 직접 묻지 않을 것
   - 아래 카테고리 중 하나에 해당할 것: CS기초, 네트워크, 데이터베이스, 시스템설계개념, AI/LLM개념, 협업/트러블슈팅 사고력
   - 앱/프론트엔드/백엔드/데브옵스/AI 직군 전원이 자기 방식으로 답할 수 있는 "개념 질문"일 것
3. 아래는 최근 출제 이력이다. 주제/문구가 겹치거나 지나치게 유사한 질문은 절대 다시 내지 마라:
${history}

4. 조건에 맞고 이력과 겹치지 않는 질문 1개를 선정해, 신입 면접 톤으로 자연스럽게 다듬어라.

반드시 아래 JSON 형식으로만 응답하라. 다른 텍스트나 마크다운 코드블록 없이 순수 JSON만 출력하라:
{
  "category": "CS|네트워크|데이터베이스|시스템설계|AI|협업",
  "question": "질문 내용 (1~2문장, 한국어)",
  "note": "이 질문을 고른 이유나 최근 트렌드와의 연관성 (1문장, 한국어)"
}`;

// Gemini API에 보낼 요청 바디 전체를 여기서 미리 JSON 문자열로 완성
const requestBody = {
  contents: [
    { role: "user", parts: [{ text: prompt }] }
  ],
  tools: [{ google_search: {} }],
  generationConfig: { temperature: 0.9 }
};

return [{ json: { requestBodyJson: JSON.stringify(requestBody) } }];

const raw = $input.first().json.candidates[0].content.parts[0].text;

// 혹시 모를 마크다운 코드블록 감싸기 방어적으로 제거
const cleaned = raw.replace(/```json\n?/g, "").replace(/```\n?/g, "").trim();

const parsed = JSON.parse(cleaned);

return [{
  json: {
    category: parsed.category,
    question: parsed.question,
    note: parsed.note
  }
}];

const id = $('Format History').item.json.openDiscussionId;

const commentBody = {
  query: "mutation($id: ID!, $body: String!) { addDiscussionComment(input: {discussionId: $id, body: $body}) { comment { id } } }",
  variables: {
    id: id,
    body: "🔒 다음 질문이 올라와서 이 토론은 마감되었습니다.\n늦게라도 답변 남기고 싶으시면 편하게 댓글 달아주세요 🐢"
  }
};

return [{
  json: {
    openDiscussionId: id,
    commentMutationJson: JSON.stringify(commentBody)
  }
}];

const id = $('Format History').item.json.openDiscussionId;

const closeBody = {
  query: "mutation($id: ID!) { closeDiscussion(input: {discussionId: $id}) { discussion { id } } }",
  variables: { id: id }
};

return [{ json: { closeMutationJson: JSON.stringify(closeBody) } }];

const category = $('Parse Gemini Response').item.json.category;
const question = $('Parse Gemini Response').item.json.question;
const note = $('Parse Gemini Response').item.json.note;

// KST 기준 오늘 날짜
const now = new Date();
const kstDate = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const yyyy = kstDate.getFullYear();
const mm = String(kstDate.getMonth() + 1).padStart(2, '0');
const dd = String(kstDate.getDate()).padStart(2, '0');
const dateStr = `${yyyy}-${mm}-${dd}`;

const title = `[${category}] ${dateStr} 오늘의 질문`;

const body = `## 🙋 오늘의 질문

**[${category}]** ${question}

---

💬 답변은 이 글의 댓글로 자유롭게 남겨주세요.
🐢 자정 넘어서 늦게 올려도 괜찮습니다.
🔖 오늘 참여가 어렵다면 이 글에 리액션만 남겨서 나중에 다시 보세요.

> ${note}
`;

const requestBody = {
  query: "mutation($repoId: ID!, $catId: ID!, $title: String!, $body: String!) { createDiscussion(input: {repositoryId: $repoId, categoryId: $catId, title: $title, body: $body}) { discussion { url } } }",
  variables: {
    repoId: "R_kgDOUlYl0g",
    catId: "DIC_kwDOUlYl0s4DGKFS",
    title: title,
    body: body
  }
};

return [{ json: { createDiscussionJson: JSON.stringify(requestBody) } }];
